-- M15: Hash ShareToken values in place (F1 requirement: stored hashed, not raw).
-- The `token` column now stores SHA-256 hex of the raw token.
-- Raw tokens are 64-char hex (256-bit); hashes are also 64-char hex, so the
-- column type is unchanged. This migration hashes any raw tokens in place.
-- New tokens are hashed by the app before insert (see src/lib/share.ts).
--
-- Idempotent: only hashes values that are not already hashes of themselves.
-- We detect raw tokens by length (64 hex chars) — hashes are also 64 hex,
-- so we use a marker: raw tokens were generated by randomBytes, hashes by
-- SHA-256. There's no reliable way to distinguish, so this migration hashes
-- ALL existing tokens. Old URLs continue to work because resolveShareToken
-- hashes the incoming token before lookup.

-- Enable pgcrypto for digest() if not already enabled.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- Hash all existing token values in place.
-- This is safe to re-run: hashing an already-hashed value would break it,
-- so we only hash values that look like raw tokens (64 hex chars) AND
-- were created before this migration. We use a guard: if the value,
-- when hashed, equals itself, it's already a hash (extremely unlikely
-- for a raw token, but the check is cheap).
--
-- Actually, the simplest idempotent approach: hash everything once.
-- If re-run, it would double-hash. So we track completion in a table.
CREATE TABLE IF NOT EXISTS "_m15_hash_completed" (
  id INTEGER PRIMARY KEY,
  completed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "_m15_hash_completed" WHERE id = 1) THEN
    -- Hash all existing ShareToken.token values in place.
    UPDATE "ShareToken"
    SET token = encode(digest(token, 'sha256'), 'hex')
    WHERE token IS NOT NULL;

    INSERT INTO "_m15_hash_completed" (id) VALUES (1);
  END IF;
END $$;
